+            </p>
+          </form>
+        </section>
+      `;
+    }
+
+    function SupportPage() {
+      return `
+        <div class="support-page">
+          <section class="hero" aria-labelledby="page-title">
+            <span class="eyebrow">Support center</span>
+            <h1 id="page-title">Get expert help when you need it.</h1>
+            <p>
