+              to your support request and keep the conversation moving.
+            </p>
+          </section>
+          ${ContactForm()}
+        </div>
+      `;
+    }
+
+    function escapeHtml(value) {
+      return value
+        .replaceAll("&", "&amp;")
+        .replaceAll('"', "&quot;")
+        .replaceAll("<", "&lt;")
+        .replaceAll(">", "&gt;");
+    }
+
+    function validateField(field) {
+      state.errors[field.id] = field.validate(state.values[field.id]);
+      return !state.errors[field.id];
+    }
+
+    function validateForm() {
+      return fields.map(validateField).every(Boolean);
+    }
+
+    function bindFormEvents() {
+      fields.forEach((field) => {
+        const input = document.getElementById(field.id);
+
+        input.addEventListener("input", (event) => {
+          state.values[field.id] = event.target.value;
+          validateField(field);
+          render();
+          document.getElementById(field.id).focus();
+        });
+
+        input.addEventListener("blur", () => {
+          validateField(field);
+          render();
+        });
+      });
+
+      document.getElementById("support-form").addEventListener("submit", (event) => {
+        event.preventDefault();
+        state.submitted = false;
+
+        if (validateForm()) {
+          state.submitted = true;
+        }
+
+        render();
+      });
+    }
+
+    function render() {
+      document.getElementById("app").innerHTML = SupportPage();
+      bindFormEvents();
+    }
+
+    render();
+  </script>
+</body>
+</html>
*** End Patch
